"""Global-memory fences and agent-scope fetch-add with explicit ordering and syncscope."""

import flydsl.expr as fx
from flydsl._mlir.dialects import llvm as _llvm_d
from flydsl.expr import arith


def _to_ptr_global(v):
    """Cast an i64 address to ``!llvm.ptr<1>`` (global address space)."""
    return _llvm_d.IntToPtrOp(
        _llvm_d.PointerType.get(address_space=1), arith.unwrap(v)
    ).result


def fence_acquire(syncscope):
    """Emit an acquire fence for the selected AMDGPU memory scope."""
    _llvm_d.FenceOp(_llvm_d.AtomicOrdering.acquire, syncscope=syncscope)


def fence_release(syncscope):
    """Emit a release fence for the selected AMDGPU memory scope."""
    _llvm_d.FenceOp(_llvm_d.AtomicOrdering.release, syncscope=syncscope)


def atomic_add_global_at(addr_i64, val, syncscope="one-as"):
    """Monotonic global fetch-add with configurable agent/system visibility."""
    ptr = _to_ptr_global(addr_i64)
    kwargs = {} if syncscope is None else {"syncscope": syncscope}
    return _llvm_d.AtomicRMWOp(
        _llvm_d.AtomicBinOp.add,
        ptr,
        arith.unwrap(val),
        _llvm_d.AtomicOrdering.monotonic,
        **kwargs,
    ).res


def atomic_add_agent(addr_i64, val):
    """Agent-scope monotonic global fetch-and-add."""
    return atomic_add_global_at(addr_i64, val, syncscope=fx.rocdl.SyncScope.Agent)

"""Layout helpers for GEMM kernels.

Parses fly layout type strings (e.g. '(4,64):(64,1)') and computes
crd2idx with plain arith ops for static layouts.
Falls back to fly dialect ops for dynamic layouts.
"""

import flydsl.expr as fx
from flydsl._mlir import ir
from flydsl.expr import arith
from flydsl.expr.arith import ArithValue
from flydsl.expr.typing import T


def _wrap(v):
    """Wrap raw ir.Value in ArithValue for operator overloading compatibility."""
    if isinstance(v, ArithValue):
        return v
    if isinstance(v, ir.Value):
        return ArithValue(v)
    return v


def _parse_dim(tok):
    """Parse a single dimension token: '?' -> None, otherwise int."""
    tok = tok.strip()
    return None if tok == "?" else int(tok)


def _find_layout_groups(s):
    """First '(<g1>):(<g2>)' in s, g1/g2 non-empty and free of ')'; None if absent.

    Same match as the search for the pattern ``\\(([^)]+)\\):\\(([^)]+)\\)``:
    the leftmost '(' whose text up to the next ')' is non-empty and is followed
    by ':(' and a non-empty run up to the next ')'.
    """
    i = s.find("(")
    while i >= 0:
        j = s.find(")", i + 1)
        if j < 0:
            return None
        if j > i + 1 and s.startswith(":(", j + 1):
            k = s.find(")", j + 3)
            if k > j + 3:
                return s[i + 1 : j], s[j + 3 : k]
        i = s.find("(", i + 1)
    return None


def _parse_layout(ly):
    """Parse '(s0,s1,...):(d0,d1,...)' -> (shapes, strides) as lists (None for '?')."""
    ly_str = str(ly.type) if hasattr(ly, "type") else str(ly)
    groups = _find_layout_groups(ly_str)
    if groups is None:
        return None
    shapes = [_parse_dim(s) for s in groups[0].split(",")]
    strides = [_parse_dim(s) for s in groups[1].split(",")]
    return shapes, strides


def _has_dynamic_strides(strides):
    """Check if any stride is dynamic (None)."""
    return any(s is None for s in strides)


def crd2idx(crd, layout):
    """Compute flat index from a coordinate tuple/list.

    For static layouts, computes with plain arith ops.
    For dynamic layouts, falls back to fx.crd2idx with fx.make_coord.
    """
    if not isinstance(crd, (list, tuple)):
        crd = [crd]
    parsed = _parse_layout(layout)

    if parsed is None or _has_dynamic_strides(parsed[1]):
        # fly.make_coord requires i32/i64, not index
        crd_i32 = []
        for c in crd:
            cv = c
            if isinstance(cv, ArithValue):
                cv = cv.ir_value() if hasattr(cv, "ir_value") else cv
            if isinstance(cv, ir.Value) and isinstance(cv.type, ir.IndexType):
                cv = arith.index_cast(T.i32, cv)
            crd_i32.append(cv)
        coord_val = fx.make_coord(*crd_i32)
        scalar = fx.get_scalar(fx.crd2idx(coord_val, layout)).ir_value()
        if not isinstance(scalar.type, ir.IndexType):
            scalar = arith.index_cast(T.index, scalar)
        return _wrap(scalar)

    _, strides = parsed
    result = None
    for coord_v, stride_v in zip(crd, strides):
        if stride_v == 0:
            continue
        term = coord_v if stride_v == 1 else coord_v * arith.index(stride_v)
        result = term if result is None else result + term
    return result if result is not None else arith.index(0)

"""Shared MXFP4 GEMM helpers: pointer/buffer setup, LDS swizzle, e8m0 scales, tile sizes."""

import flydsl.expr as fx
from flydsl._mlir import ir
from flydsl.expr import math as fmath
from flydsl.expr.typing import T

from . import buffer_ops
from . import dpp_utils

kStages = 2
kBS_stride_k0_dw = 64


def _raw(v):
    if not isinstance(v, ir.Value) and hasattr(v, "ir_value"):
        return v.ir_value()
    return v


def _lds_ptr3(base_i32, byte_off_i32):
    ptr_ty = fx.PointerType.get(T.i8, fx.AddressSpace.Shared)
    return fx.to_llvm_ptr(fx.inttoptr(ptr_ty, fx.Int64(base_i32 + byte_off_i32)))


def _gep3(base_ptr, byte_off_i32):
    return buffer_ops.get_element_ptr(
        base_ptr, byte_offset=byte_off_i32, elem_type=T.i8
    )


def _global_base_ptr1(addr_i64):
    ptr_ty = fx.PointerType.get(T.i8, fx.AddressSpace.Global)
    return fx.to_llvm_ptr(fx.inttoptr(ptr_ty, fx.Int64(addr_i64)))


def _gep1(base_ptr, byte_off_i32):
    return buffer_ops.get_element_ptr(
        base_ptr, byte_offset=byte_off_i32, elem_type=T.i8
    )


def _global_ptr1(arg, byte_off_i32):
    return _gep1(_global_base_ptr1(arg), byte_off_i32)


def _buffer_rsrc(addr_i64, num_records_bytes):
    return buffer_ops.create_buffer_resource_from_addr(
        fx.Int64(addr_i64), num_records_bytes=num_records_bytes
    )


def _lds_swizzle_mask(row, row_bytes=128):
    """XOR16 swizzle for an FP4 LDS row of `row_bytes`; permutes its 16-byte columns."""
    assert row_bytes in (64, 128), f"unsupported FP4 LDS row width {row_bytes}"
    return (row & fx.Int32(2 * (row_bytes // 16) - 2)) << fx.Int32(3)


def _fabs_f32(x):
    return fmath.absf(x)


def _e8m0_roundup(amax_f32):
    wi = (amax_f32 * fx.Float32(1.0 / 6.0)).bitcast(fx.Int32)
    bexp = (wi + fx.Int32(0x7FFFFF)).shrui(fx.Int32(23)) & fx.Int32(0xFF)
    lt = fx.Uint32(bexp) < fx.Uint32(254)
    return lt.select(bexp, fx.Int32(254))


def _e8m0_from_amax(amax_f32):
    e8m0 = _e8m0_roundup(amax_f32)
    qscale = (e8m0 << fx.Int32(23)).bitcast(fx.Float32)
    return e8m0, qscale


def _umax_i32(a, b):
    is_gt = fx.Uint32(a) > fx.Uint32(b)
    return is_gt.select(a, b)


def _dpp_umax_step(a32, dpp_ctrl):
    swapped = dpp_utils.update_dpp_i32(a32, a32, dpp_ctrl, 0xF, 0xF, True)
    return _umax_i32(a32, fx.Int32(swapped))


def _inline_dpp_quad_amax(a32):
    return _dpp_umax_step(_dpp_umax_step(a32, 0xB1), 0x4E)


def k_half_for(k):
    return k // 2


def k_tiles_total_for(k, BK):
    return k // BK


def kunroll_for(k, BK):
    return k_tiles_total_for(k, BK) - kStages


def kas_c_k1_for(k):
    return (k // 32) // 4 // 2


def kbs_c_k1_for(k):
    return (k // 32) // 4 // 2


def kbs_stride_n0_dw_for(k):
    return kbs_c_k1_for(k) * 64


def kas_per_chunk_dw_for(k):
    return kas_c_k1_for(k) * 64


def num_n_blocks_for(n, BN):
    return n // BN


def kbs_c_n1_for(n):
    return n // 16 // 2


def kbs_per_expert_dw_for(n, k):
    return kbs_c_n1_for(n) * kbs_stride_n0_dw_for(k)


def bq_bytes_for(ne, n, k):
    return ne * n * k_half_for(k)


def bscale_bytes_for(ne, n, k):
    return ne * kbs_per_expert_dw_for(n, k) * 4


def kmchunks_for(BM):
    return BM // 16


def lds_acc_bytes_for(rows, BN):
    return rows * BN * 4
